11	function ClampHistoryLimit(limit: number | undefined): number
12	{
13	  if (limit === undefined || !Number.isFinite(limit) || limit <= 0)
14	  {
15	    return x_defaultHistoryLimit;
16	  }
17	
18	  return Math.min(Math.floor(limit), x_maxHistoryLimit);
19	}
20	
21	function EnvelopesFromEntries(entries: SessionLogEntry[]): ChatEnvelope[]
22	{
23	  return entries.map((entry) => entry.envelope);
24	}
25	
26	function SequenceBounds(entries: SessionLogEntry[]): {
27	  oldestSequence: number | null;
28	  newestSequence: number | null;
29	}
30	{
31	  if (entries.length === 0)
32	  {
33	    return {
34	      oldestSequence: null,
35	      newestSequence: null,
36	    };
37	  }
38	
39	  return {
40	    oldestSequence: entries[0].sequence,
41	    newestSequence: entries[entries.length - 1].sequence,
42	  };
43	}
44	
45	function ValidateHistoryRequest(request: HistoryPageRequest): HistoryPageRequest
46	{
47	  const hasBefore = request.before !== undefined;
48	  const hasAfter = request.after !== undefined;
49	
50	  if (hasBefore && hasAfter)
51	  {
52	    throw new StorageError(
53	      "invalid_history_request",
54	      "history request cannot include both before and after cursors",
55	    );
56	  }
57	
58	  return request;
59	}
60	
61	function BuildLatestPage(entries: SessionLogEntry[], limit: number): HistoryPage
62	{
63	  const pageEntries = entries.slice(Math.max(0, entries.length - limit));
64	  const bounds = SequenceBounds(pageEntries);
65	  const allBounds = SequenceBounds(entries);
66	
67	  return {
68	    direction: "latest",
69	    envelopes: EnvelopesFromEntries(pageEntries),
70	    oldestSequence: bounds.oldestSequence,
71	    newestSequence: bounds.newestSequence ?? allBounds.newestSequence,
72	    hasMoreBefore: entries.length > pageEntries.length,
73	    hasMoreAfter: false,
74	  };
75	}
