import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";

import { CreateStoragePaths, type StoragePaths } from "../../src/storage/paths.js";

export async function WithTempStorage<T>(
  callback: (paths: StoragePaths) => Promise<T>,
): Promise<T>
{
  const repoRoot = await mkdtemp(path.join(tmpdir(), "sheaf-chat-storage-"));

  try
  {
    return await callback(CreateStoragePaths(repoRoot));
  }
  finally
  {
    await rm(repoRoot, { recursive: true, force: true });
  }
}
import assert from "node:assert/strict";
import test from "node:test";

import { StorageError } from "../../src/storage/errors.js";
import { ValidatePileName, ValidateSessionId } from "../../src/storage/validation.js";

test("ValidatePileName rejects traversal, reserved names, and invalid stems", () =>
{
  assert.throws(
    () => ValidatePileName(""),
    (error: unknown) => error instanceof StorageError && error.code === "invalid_pile",
  );
  assert.throws(() => ValidatePileName("."), StorageError);
  assert.throws(() => ValidatePileName(".."), StorageError);
  assert.throws(() => ValidatePileName("bad/name"), StorageError);
  assert.throws(() => ValidatePileName("bad\\name"), StorageError);
  assert.throws(() => ValidatePileName("-leading-dash"), StorageError);
});

test("ValidatePileName rejects Unicode normalization differences", () =>
{
  const nfdName = "e\u0301team";
  const nfcName = nfdName.normalize("NFC");

  assert.notEqual(nfdName, nfcName);
  assert.throws(
    () => ValidatePileName(nfdName),
    (error: unknown) => error instanceof StorageError && error.code === "invalid_name",
  );
  assert.equal(ValidatePileName(`a${nfcName.slice(1)}`), `a${nfcName.slice(1)}`);
});

test("ValidateSessionId accepts generated ids and rejects unsafe values", () =>
{
  assert.equal(ValidateSessionId("01Jabc"), "01Jabc");
  assert.throws(() => ValidateSessionId(".."), StorageError);
  assert.throws(() => ValidateSessionId("bad/name"), StorageError);
});
import assert from "node:assert/strict";
import { mkdir, symlink, writeFile } from "node:fs/promises";
import path from "node:path";
import test from "node:test";

import { StorageError } from "../../src/storage/errors.js";
import {
  AssertPathWithinRoot,
  CreateStoragePaths,
  ResolvePileDirectory,
  ResolveRootDirectory,
} from "../../src/storage/paths.js";
import { WithTempStorage } from "./helpers.js";

test("ResolveRootDirectory stores absolute paths for relative inputs", async () =>
{
  await WithTempStorage(async (paths) =>
  {
    const resolved = ResolveRootDirectory(paths.repoRoot, "projects/example-app");
    assert.equal(resolved, path.resolve(paths.repoRoot, "projects/example-app"));
    assert.ok(path.isAbsolute(resolved));
  });
});

test("ResolvePileDirectory rejects traversal through pile names", async () =>
{
  await WithTempStorage(async (paths) =>
  {
    assert.throws(
      () => ResolvePileDirectory(paths, "../escape"),
      (error: unknown) => error instanceof StorageError,
    );
  });
});

test("AssertPathWithinRoot rejects symlink escapes from the piles root", async () =>
{
  await WithTempStorage(async (paths) =>
  {
    await mkdir(paths.pilesDir, { recursive: true });
    const outsideDir = path.join(paths.repoRoot, "outside");
    const linkPath = path.join(paths.pilesDir, "linked");
    await mkdir(outsideDir, { recursive: true });
    await writeFile(path.join(outsideDir, "secret.txt"), "nope", "utf8");
    await symlink(outsideDir, linkPath, "dir");

    await assert.rejects(
      () => AssertPathWithinRoot(linkPath, paths.pilesDir),
      (error: unknown) => error instanceof StorageError && error.code === "path_escape",
    );
  });
});
import assert from "node:assert/strict";
import test from "node:test";

import { WriteInitialManifest } from "../../src/storage/manifests.js";
import { CreatePile, ListPiles, ManifestExists } from "../../src/storage/piles.js";
import { AllocateSessionShell, x_defaultExtensionVersion } from "../../src/storage/sessionLog.js";
import { WithTempStorage } from "./helpers.js";

test("CreatePile and ListPiles report empty and populated piles", async () =>
{
  await WithTempStorage(async (paths) =>
  {
    const created = await CreatePile(paths, "team.alpha");
    assert.equal(created.pile, "team.alpha");
    assert.equal(created.sessionCount, 0);
    assert.equal(created.latestUpdatedAt, null);

    const piles = await ListPiles(paths);
    assert.deepEqual(piles, [created]);
  });
});

test("ListPiles counts manifests and tracks latest update time", async () =>
{
  await WithTempStorage(async (paths) =>
  {
    await CreatePile(paths, "default");
    const allocated = await AllocateSessionShell(paths, "default", "projects/demo", {
      provider: "openai",
      id: "gpt-5-codex",
    });
    await WriteInitialManifest(paths, {
      pile: "default",
      sessionId: allocated.sessionId,
      chatName: "First chat",
      description: "demo",
      rootDirectory: allocated.provisionalSession.rootDirectory,
      model: allocated.provisionalSession.model,
      extensionVersion: x_defaultExtensionVersion,
    });

    const piles = await ListPiles(paths);
    assert.equal(piles.length, 1);
    assert.equal(piles[0]?.sessionCount, 1);
    assert.ok(piles[0]?.latestUpdatedAt);
    assert.equal(await ManifestExists(paths, "default", allocated.sessionId), true);
  });
});

